// prog1: Matrix Saddle Point
// A saddle point: max in its row AND min in its column
// When equal elements tie for max/min, they all count
#include <iostream>
using namespace std;
int main(){
    int n, m;
    cin >> n >> m;
    int a[100][100];
    for(int i=0;i<n;i++)
        for(int j=0;j<m;j++)
            cin >> a[i][j];

    bool found = false;
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            // Check if a[i][j] is max in row i
            bool rowMax = true;
            for(int k=0;k<m;k++){
                if(a[i][k] > a[i][j]){
                    rowMax = false;
                    break;
                }
            }
            if(!rowMax) continue;

            // Check if a[i][j] is min in column j
            bool colMin = true;
            for(int k=0;k<n;k++){
                if(a[k][j] < a[i][j]){
                    colMin = false;
                    break;
                }
            }
            if(colMin){
                cout << i+1 << " " << j+1 << " " << a[i][j] << endl;
                found = true;
            }
        }
    }
    if(!found) cout << "NONE" << endl;
    return 0;
}

