// prog2: Insertion Sort Move Count
// Count moves = number of a[j+1]=a[j] shifts
// Write-back of key does NOT count
// Use strict > for comparison (equal elements don't move)
#include <iostream>
using namespace std;
int main(){
    int n;
    cin >> n;
    long long a[1000];
    for(int i=0;i<n;i++) cin >> a[i];

    long long moves = 0;
    for(int i=1;i<n;i++){
        long long key = a[i];
        int j = i-1;
        while(j>=0 && a[j] > key){
            a[j+1] = a[j];
            j--;
            moves++;
        }
        a[j+1] = key;
    }

    for(int i=0;i<n;i++){
        if(i>0) cout << " ";
        cout << a[i];
    }
    cout << endl;
    cout << moves << endl;
    return 0;
}

